from typing import FrozenSet, Tuple
Literal = Tuple[str, bool]
State = FrozenSet[Literal]
def opposite(lit: Literal) -> Literal:
    return lit[0], not lit[1]
def revise(state: State, lit: Literal) -> State:
    return frozenset((set(state) - {opposite(lit)}) | {lit})
if __name__ == "__main__":
    state = frozenset({("a", True), ("a", False), ("b", True)})
    print("initial:", state)
    print("positive update:", revise(state, ("a", True)))
    print("negative update:", revise(state, ("a", False)))

from itertools import product
from typing import FrozenSet, Iterator, Tuple
Literal = Tuple[str, bool]
State = FrozenSet[Literal]
def states(atoms: tuple[str, ...]) -> Iterator[State]:
    ls = tuple((a, s) for a in atoms for s in (False, True))
    for mask in product((False, True), repeat=len(ls)):
        yield frozenset(x for x, take in zip(ls, mask) if take)
def consistent(b: State) -> bool:
    return all((a, not s) not in b for a, s in b)
def conflict_free(b: State) -> bool:
    return all((a, not s) not in b for a, s in b)
if __name__ == "__main__":
    sample = list(states(("a", "b", "c")))
    print(len(sample), sum(map(consistent, sample)))
    print(all(consistent(b) == conflict_free(b) for b in sample))

from itertools import product
from typing import Callable, Dict, Iterator, Sequence, Tuple, TypeVar
T = TypeVar("T")
def words(alphabet: Sequence[T], maximum: int) -> Iterator[Tuple[T, ...]]:
    for n in range(maximum + 1):
        yield from product(alphabet, repeat=n)
def collision(alphabet: Sequence[T], maximum: int, memory: Callable[[Tuple[T, ...]], int]) -> tuple[Tuple[T, ...], Tuple[T, ...], int]:
    seen: Dict[int, Tuple[T, ...]] = {}
    for word in words(alphabet, maximum):
        value = memory(word)
        if value in seen:
            return seen[value], word, value
        seen[value] = word
    raise ValueError("No collision in search region")
if __name__ == "__main__":
    print(collision(("x",), 5, lambda w: len(w) % 5))

